async function connectFolder(){
 if(switching)return;
 setSwitching(true);
 try{
  const name=await chooseWorkspace();
  const disk=await listWorkspaceProjects();
  await storeProject(liveProject.current,projectId);
  if(disk.length){
   const selectedDisk=disk.find(p=>p.id===projectId)??disk[0];
   const restored=await readWorkspaceProject(selectedDisk.id);
   await storeProject(restored,selectedDisk.id);
   setProject(restored);setProjectId(selectedDisk.id);setProjectList(disk);setSelected(null);setTakeId(null);setViewSnapshot(null);setDirty(false);
  }else{
   const browser=await listProjects();
   for(const item of browser)await writeWorkspaceProject(await loadSavedProject(item.id),item.id);
   await writeWorkspaceProject(liveProject.current,projectId);
   setProjectList(await listWorkspaceProjects());
  }
  setConnectedFolder(name);notify('Workspace connected. Scenes now save into the selected folder.');
 }catch(e){if((e as DOMException).name!=='AbortError')notify('Could not connect folder: '+String(e));}
 finally{setSwitching(false);}
}
